                if (damage_to_monster === 0) continue; // Cannot defeat monster

                // Calculate time to defeat monster
                const time_to_kill = Math.ceil(HPM / damage_to_monster);

                // Calculate damage monster deals to Yang per second
                const damage_to_yang = Math.max(0, ATKM - def);

                // Calculate required HP for Yang
                let required_hp = 1;
                if (damage_to_yang > 0) {
                    required_hp = damage_to_yang * time_to_kill + 1;
