const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

let inputs = [];
rl.on('line', (line) => {
    inputs.push(line.split(' ').map(Number));
}).on('close', () => {
    const [HPY, ATKY, DEFY] = inputs[0];
    const [HPM, ATKM, DEFM] = inputs[1];
    const [h, a, d] = inputs[2];

    let min_cost = Infinity;

    for (let add_atk = 0; add_atk <= 200; add_atk++) {
        const new_atk = ATKY + add_atk;
        if (new_atk <= DEFM) continue;

        for (let add_def = 0; add_def <= 200; add_def++) {
            const new_def = DEFY + add_def;
            const dmg_per_sec_m = Math.max(0, ATKM - new_def);

            if (dmg_per_sec_m === 0) {
                const time = Math.ceil(HPM / (new_atk - DEFM));
                const cost = add_atk * a + add_def * d;
                if (cost < min_cost) min_cost = cost;
            } else {
                const time = Math.ceil(HPM / (new_atk - DEFM));
                const required_hp = time * dmg_per_sec_m + 1;
                const add_hp = Math.max(0, required_hp - HPY);
                const cost = add_hp * h + add_atk * a + add_def * d;
                if (cost < min_cost) min_cost = cost;
            }
        }
    }

    console.log(min_cost);
});
