```javascript
const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let inputs = [];
rl.on('line', (line) => {
    inputs.push(line.split(' ').map(Number));
}).on('close', () => {
    const [HPY, ATKY, DEFY] = inputs[0];
    const [HPM, ATKM, DEFM] = inputs[1];
    const [h, a, d] = inputs[2];

    let min_cost = Infinity;

    // Iterate over possible ATK and DEF values
    for (let atk = ATKY; atk <= ATKY + 200; atk++) {
        for (let def = DEFY; def <= DEFY + 200; def++) {
            // Calculate damage per second to monster
            let dmg_to_monster = atk - DEFM;
            if (dmg_to_monster <= 0) continue; // Cannot damage monster

            // Calculate time to kill monster
            let time_to_kill = Math.ceil(HPM / dmg_to_monster);

            // Calculate damage per second to Yang
            let dmg_to_yang = ATKM - def;
            if (dmg_to_yang <= 0) {
                // Monster cannot damage Yang, any HP > 0 is sufficient
                let cost = (atk - ATKY) * a + (def - DEFY) * d;
                if (cost < min_cost) min_cost = cost;
            } else {
                // Yang needs enough HP to survive
                let required_hp = dmg_to_yang * time_to_kill + 1;
                if (required_hp <= HPY) {
                    // No need to buy HP
                    let cost = (atk - ATKY) * a + (def - DEFY) * d;
                    if (cost < min_cost) min_cost = cost;
                } else {
                    // Need to buy HP
                    let hp_needed = required_hp - HPY;
                    let cost = hp_needed * h + (atk - ATKY) * a + (def - DEFY) * d;
                    if (cost < min_cost) min_cost = cost;
                }
            }
        }
    }

    console.log(min_cost);
});
